{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Abiraterone acetate, a steroid-like molecule, has an estimated absolute oral bioavailability of <10% in humans after 1000 mg tablets, with food increasing AUC up to tenfold, indicating very low systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Testosterone, a steroid with a similar fused-ring scaffold, has an oral bioavailability of 7.5% in healthy volunteers after IV-oral comparison, and other studies report ~3.6%, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Mometasone, a steroid, has reported oral bioavailability <1% in humans, demonstrating that steroid scaffolds with polar groups can undergo extensive first-pass metabolism and very low systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Fulvestrant, a steroid with a phenolic hydroxyl like the query, has low oral bioavailability and presystemic metabolism in animals and humans, requiring intramuscular administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues are steroid-like molecules with measured oral bioavailability below 10% (mostly <10%, some <1%), and the query shares the steroid scaffold and phenolic hydroxyl features associated with poor absorption and first-pass metabolism. Therefore the query is predicted to have F < 20% (low).",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the exact query molecule; prediction relies on high-transfer steroid analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

